const connectionDiagnostics=[];
function classifyConnectionIssue(kind,detail,meta={}){
 const raw=String(detail||"").trim(),lower=raw.toLowerCase();
 let category=kind||"CONNECTION EVENT",explanation=raw||"No additional detail was supplied.";
 if(kind==="NETWORK"){
  category="NETWORK INTERRUPTION";
  explanation=meta.online===false?"This browser reports that the device is offline. Check Wi-Fi/mobile data; no trade should be attempted.":"The browser network changed. The exact cause may not be exposed by the browser.";
 }else if(kind==="WEBSOCKET_CLOSE"){
  const code=Number(meta.code);
  if(meta.manual){category="MANUAL DISCONNECT";explanation="The disconnect button was used. This is not a broker failure.";}
  else if(meta.online===false){category="NETWORK INTERRUPTION";explanation="The socket closed while the browser reports offline. Restore internet before reconnecting.";}
  else if(code===1000){category="SOCKET CLOSED NORMALLY";explanation="Deriv closed the WebSocket normally (code 1000). The close event alone does not identify why the session ended.";}
  else if(code===1001){category="REMOTE ENDPOINT LEFT";explanation="The WebSocket endpoint or browser is going away (code 1001). Check session state and reconnect once stable.";}
  else if(code===1006){category="ABNORMAL SOCKET DROP";explanation="The socket closed without a normal close handshake (code 1006). Common possibilities include network interruption, browser sleep, or remote service interruption; this code does not prove which one.";}
  else if(code===1008){category="CONNECTION POLICY REJECTED";explanation="The WebSocket endpoint closed the connection for a policy reason (code 1008). Re-check authorization/session and account access.";}
  else if(code===1011){category="REMOTE SERVICE ERROR";explanation="The remote endpoint reported an internal error (code 1011). Wait briefly and retry; do not repeat any uncertain purchase.";}
  else {category="WEBSOCKET CLOSED";explanation="WebSocket close code "+(Number.isFinite(code)?code:"unknown")+". "+(meta.reason||"The server supplied no further reason.");}
 }else if(kind==="WEBSOCKET_ERROR"){
  category="WEBSOCKET ERROR";
  explanation="The browser reported a socket error but hides the underlying network detail. The close event and recent network status are shown separately.";
 }else if(kind==="DERIV_API"){
  const code=String(meta.code||"").toLowerCase();
  if(/auth|token|oauth|permission|authorize/.test(code+" "+lower)){category="AUTHORIZATION / SESSION";explanation=raw+" Check that the Deriv authorization is still valid and that this account is approved for Options trading.";}
  else if(/rate|limit|throttl/.test(code+" "+lower)){category="API RATE LIMIT";explanation=raw+" Wait before retrying; do not send repeated requests.";}
  else if(/market|symbol|contract|proposal|buy|balance|portfolio/.test(code+" "+lower)){category="DERIV REQUEST REJECTED";explanation=raw+" This is a request-level rejection, not proof that the WebSocket disconnected.";}
  else {category="DERIV API ERROR";explanation=raw+" The server rejected a request; this does not by itself establish a connection failure.";}
 }else if(kind==="RECONCILIATION"){
  category="BROKER RECONCILIATION";
 }else if(kind==="RISK"){
  category="RISK PAUSE — NOT DISCONNECTED";
 }
 const item={at:Date.now(),category,detail:explanation,code:meta.code??null,closeReason:meta.reason??"",online:navigator.onLine};
 connectionDiagnostics.unshift(item);connectionDiagnostics.splice(8);
 renderConnectionDiagnostics();
 return item;
}
function renderConnectionDiagnostics(){
 const panel=$("bt-connection-diagnostics");if(!panel)return;
 const latest=connectionDiagnostics[0];
 const latestEl=$("bt-connection-diagnosis");
 const historyEl=$("bt-connection-history");
 if(latestEl)latestEl.textContent=latest?latest.category+" · "+latest.detail:"No disconnection recorded in this page session. Connection health is monitored automatically.";
 if(historyEl)historyEl.innerHTML=connectionDiagnostics.length?connectionDiagnostics.slice(0,5).map(x=>"<div style='padding:6px 0;border-top:1px solid #263951'><b>"+new Date(x.at).toLocaleString()+" · "+esc(x.category)+"</b><br>"+esc(x.detail)+(x.code!==null?" · code "+esc(x.code):"")+"</div>").join(""):"No events recorded.";
}
window.addEventListener("offline",()=>{classifyConnectionIssue("NETWORK","Browser offline",{online:false});reconciliationReady=false;proposal=null;proposalContext=null;proposalReceivedAt=0;latestAnalysisSignal=null;AI_GUARD.signal=null;autoQuotePending=false;autoQuoteSignal=null;clearTimeout(proposalTimer);proposalTimer=null;$("bt-buy").disabled=true;$("bt-conn").textContent="OFFLINE · TRADING PAUSED";setAIGuard("AMBER","Internet connection lost. Existing signals and quotes have been invalidated. Wait for internet restoration, fresh Deriv authentication and broker reconciliation.");renderRisk();});
window.addEventListener("online",()=>{classifyConnectionIssue("NETWORK","Browser reports internet connectivity restored",{online:true});if(sessionId&&account)scheduleAccountReconnect("Internet restored. Re-authenticating Deriv and reconciling broker positions before trading can resume.");});

function todayKey(){const d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");}
function riskStorageKey(){return "berur-risk-v1:"+(account?.account_id||account?.id||"unselected");}
function riskControlsKey(){return "berur-risk-controls-v1:"+(account?.account_id||account?.id||"unselected");}
function moneyFromCapital(pct){const balance=Number(accountBalance);return Number.isFinite(balance)&&balance>0?Math.floor((balance*pct/100+Number.EPSILON)*100)/100:0;}
function saveRiskControls(){try{localStorage.setItem(riskControlsKey(),JSON.stringify({mode:"capital-percentage-v1"}));}catch{}}
function loadRiskControls(){syncCapitalRisk(true);}
function syncCapitalRisk(resetStake=false){
 const balance=Number(accountBalance);if(!Number.isFinite(balance)||balance<=0)return false;
 const base=CAPITAL_RISK.baseStake;
 const cap=moneyFromCapital(CAPITAL_RISK.maxTradePct),exposure=moneyFromCapital(CAPITAL_RISK.maxExposurePct);
 const set=(id,value)=>{const el=$(id);if(el)el.value=Number(value).toFixed(2);};
 set("bt-base",base);set("bt-cap",cap);set("bt-total-cap",exposure);
 set("bt-sl",moneyFromCapital(CAPITAL_RISK.sessionLossPct));set("bt-tp",moneyFromCapital(CAPITAL_RISK.sessionProfitPct));
 set("bt-daily-sl",moneyFromCapital(CAPITAL_RISK.dailyLossPct));set("bt-daily-tp",moneyFromCapital(CAPITAL_RISK.dailyProfitPct));
 if(resetStake||!Number.isFinite(Number($("bt-stake")?.value))||Number($("bt-stake").value)>cap)set("bt-stake",base);
 set("bt-multiplier",1);set("bt-steps",0);
 const note=$("bt-capital-risk-note");if(note)note.textContent="Live capital: "+balance.toFixed(2)+" "+(account?.currency||"")+" · Fixed base stake "+CAPITAL_RISK.baseStake.toFixed(2)+" · Max trade/exposure "+CAPITAL_RISK.maxTradePct+"% · Daily loss "+CAPITAL_RISK.dailyLossPct+"% · Daily target "+CAPITAL_RISK.dailyProfitPct+"%. Deriv minimum stake: "+CAPITAL_RISK.minStake.toFixed(2)+". Values recalculate from the latest broker balance.";
 saveRiskControls();return true;
}
function loadRiskState(){riskKey=riskStorageKey();try{activeSessionNo=Number(localStorage.getItem(sessionCounterKey())||0);}catch{activeSessionNo=0;}const sessionEl=$("bt-session-number");if(sessionEl)sessionEl.textContent=activeSessionNo?String(activeSessionNo).padStart(3,"0"):"—";try{activeSessionEntryNo=activeSessionNo?Number(localStorage.getItem(entryCounterKey())||0):0;}catch{activeSessionEntryNo=0;}if($("bt-session-entries"))$("bt-session-entries").textContent=String(activeSessionEntryNo);const day=todayKey();try{const v=JSON.parse(localStorage.getItem(riskKey)||"null");riskState=v&&v.day===day?{...riskState,...v,sessionPL:Number(v.sessionPL)||0}:{day,dailyPL:0,sessionPL:0,dailyTrades:0,lossStreak:0,halted:false,reason:""};}catch{riskState={day,dailyPL:0,sessionPL:0,dailyTrades:0,lossStreak:0,halted:false,reason:""};}loadRiskControls();restoreAIGuard();saveRiskState();renderRisk();renderJournal();renderPendingPurchaseLock();}
function saveRiskState(){if(riskKey)try{localStorage.setItem(riskKey,JSON.stringify(riskState));}catch{}}
function ensureRiskDay(){const day=todayKey();if(!riskState.day){riskState.day=day;return;}if(riskState.day!==day){riskState.day=day;riskState.dailyPL=0;riskState.dailyTrades=0;riskState.halted=false;riskState.reason="";saveRiskState();}}
function riskLimitReason(startingNewSession=false){ensureRiskDay();const balance=Number(accountBalance);if(!Number.isFinite(balance)||balance<=0)return "Waiting for a verified live Deriv balance. Trading is blocked until capital is confirmed.";const cap=moneyFromCapital(CAPITAL_RISK.maxTradePct),stake=Number($("bt-stake")?.value||0),loss=moneyFromCapital(CAPITAL_RISK.sessionLossPct),target=moneyFromCapital(CAPITAL_RISK.sessionProfitPct),dailyLoss=moneyFromCapital(CAPITAL_RISK.dailyLossPct),dailyTarget=moneyFromCapital(CAPITAL_RISK.dailyProfitPct);if(cap<CAPITAL_RISK.minStake)return "Capital too small for the Deriv minimum stake within the "+CAPITAL_RISK.maxTradePct+"% risk cap. No trade is allowed.";if(!(stake>=CAPITAL_RISK.minStake&&stake<=cap))return "Stake must be at least "+CAPITAL_RISK.minStake.toFixed(2)+" and must not exceed "+CAPITAL_RISK.maxTradePct+"% of current capital ("+cap.toFixed(2)+").";if(!startingNewSession&&Number(riskState.sessionPL||0)<=-loss)return "Session stop-loss reached ("+CAPITAL_RISK.sessionLossPct+"% of capital). New trades are paused.";if(!startingNewSession&&Number(riskState.sessionPL||0)>=target)return "Session take-profit reached ("+CAPITAL_RISK.sessionProfitPct+"% of capital). New trades are paused.";if(Number(riskState.dailyPL||0)<=-dailyLoss)return "Daily stop-loss reached ("+CAPITAL_RISK.dailyLossPct+"% of capital). New trades are paused until the next day.";if(Number(riskState.dailyPL||0)>=dailyTarget)return "Daily take-profit reached ("+CAPITAL_RISK.dailyProfitPct+"% of capital). New trades are paused until the next day.";return "";}
function aiGuardStorageKey(){return "berur-ai-guard-v1:"+(account?.account_id||account?.id||"unselected");}
function persistAIGuard(){if(!account)return;try{localStorage.setItem(aiGuardStorageKey(),JSON.stringify({state:AI_GUARD.state,reason:AI_GUARD.reason,locked:AI_GUARD.locked,at:Date.now(),recentLossEvents,quoteIntegrityEvents}));}catch{}}
function restoreAIGuard(){AI_GUARD.state="AMBER";AI_GUARD.reason="Waiting for a fresh qualified signal and stable market feed.";AI_GUARD.locked=false;signalStability.clear();recentLossEvents.length=0;quoteIntegrityEvents.length=0;try{const saved=JSON.parse(localStorage.getItem(aiGuardStorageKey())||"null");if(Array.isArray(saved?.recentLossEvents))recentLossEvents.push(...saved.recentLossEvents.filter(x=>Number(x?.at)>Date.now()-CAPITAL_RISK.rapidLossWindowMs&&Number(x?.loss)>0));if(Array.isArray(saved?.quoteIntegrityEvents))quoteIntegrityEvents.push(...saved.quoteIntegrityEvents.filter(x=>Number(x)>Date.now()-60000));if(saved?.locked){AI_GUARD.state="LOCKED";AI_GUARD.reason=String(saved.reason||"A previous session triggered a safety lock.");AI_GUARD.locked=true;}}catch{}const el=$("bt-ai-state"),msg=$("bt-ai-reason");if(el){el.textContent=AI_GUARD.locked?"LOCKED — MANUAL REVIEW":AI_GUARD.state;el.style.color=AI_GUARD.locked?"#ff7188":AI_GUARD.state==="AMBER"?"#ffc65c":"#35e0a2";}if(msg)msg.textContent=AI_GUARD.reason;renderAIGuardSignal();}
function clearAIGuardAfterReview(){if(!account||account.account_type!=="demo")throw Error("Manual review reset is available only on the connected DEMO account.");if(openContracts.size||busy||readPendingPurchase())throw Error("Wait until all contracts are settled and the purchase safety lock is clear.");if(!confirm("Confirm that you reviewed Deriv account history, settled contracts, current balance and feed health. Clear the AI safety lock for this DEMO account?"))return;try{localStorage.removeItem(aiGuardStorageKey());}catch{}AI_GUARD.locked=false;AI_GUARD.state="AMBER";AI_GUARD.reason="Manual review acknowledged. Waiting for a new fresh qualified signal before allowing trades.";signalStability.clear();restoreAIGuard();renderRisk();say("AI safety lock acknowledged and cleared. Trading remains paused until a fresh qualified signal passes the guard.");}
function recordQuoteIntegrityIssue(reason){const now=Date.now();quoteIntegrityEvents.push(now);while(quoteIntegrityEvents.length&&now-quoteIntegrityEvents[0]>60000)quoteIntegrityEvents.shift();if(quoteIntegrityEvents.length>=2)setAIGuard("RED","Repeated invalid Deriv quote data detected within 60 seconds. Possible feed or contract-data integrity problem; manual review required.",true);else setAIGuard("AMBER",reason+" No purchase was sent; waiting for a fresh valid quote.");}
function renderAIGuardSignal(){const el=$("bt-ai-signal");if(!el)return;const s=AI_GUARD.signal;if(!s){el.textContent="No current executable signal. Waiting for a fresh candidate.";return;}const age=Math.max(0,Math.round((Date.now()-Number(s.marketUpdatedAt||0))/1000));const expires=Math.max(0,Math.round((Number(s.expiresAt||0)-Date.now())/1000));const contract=String(s.contract||"").replace("DIGITOVER","OVER").replace("DIGITUNDER","UNDER").replace("DIGITEVEN","EVEN").replace("DIGITODD","ODD").replace("DIGITMATCH","MATCH").replace("DIGITDIFF","DIFFERS").replace("CALL","RISE").replace("PUT","FALL");const barrier=Number.isInteger(Number(s.barrier))?" "+s.barrier:"";el.textContent=(AI_GUARD.state==="GREEN"&&!AI_GUARD.locked?"GUARD-APPROVED SIGNAL: ":"LAST EVALUATED SIGNAL — NOT APPROVED: ")+marketLabel(s.symbol)+" · "+contract+barrier+" · evidence "+Number(s.evidenceScore||0)+"/100 (heuristic, not win probability) · sample "+Number(s.sample||0)+" · live quote changes "+Number(s.liveObservations||0)+" · feed age "+age+"s · signal expires in "+expires+"s. A fresh broker proposal/price check is still required before purchase. Signal ID: "+String(s.signalId||"—");}
function setAIGuard(state,reason,lock=false){if(AI_GUARD.locked&&!lock)return;const previousState=AI_GUARD.state;AI_GUARD.state=state;AI_GUARD.reason=String(reason||"");AI_GUARD.locked=AI_GUARD.locked||!!lock;persistAIGuard();const el=$("bt-ai-state"),msg=$("bt-ai-reason");if(el){el.textContent=AI_GUARD.locked?"LOCKED — MANUAL REVIEW":(state==="AMBER"&&auto?"AMBER — AUTO-RESUME ARMED":state);el.style.color=AI_GUARD.locked||state==="RED"?"#ff7188":state==="AMBER"?"#ffc65c":"#35e0a2";}if(msg)msg.textContent=AI_GUARD.reason;renderAIGuardSignal();renderTradeReadiness();if((AI_GUARD.locked||state==="RED")&&auto)stopAuto(AI_GUARD.reason||"AI protection stopped automatic trading.");else if(state==="GREEN"&&auto&&previousState!=="GREEN"){say("AI GUARD GREEN · Market/feed checks recovered. Automatic DEMO scanning has resumed.");setTimeout(autoStep,150);}if($("bt-buy")&&state!=="GREEN")$("bt-buy").disabled=true;}
function observeAIGuardSignal(s){if(AI_GUARD.locked)return;AI_GUARD.signal=s&&typeof s==="object"?{...s}:null;if(!s||!coherentSignal(s)){setAIGuard("AMBER","Waiting for a fresh signal that passes the evidence and expiry checks.");return;}const now=Date.now(),side=String(s.contract||"").replace("DIGIT",""),symbol=String(s.symbol||"");const prev=signalStability.get(symbol)||{side:"",flips:[]};prev.flips=prev.flips.filter(t=>now-t<30000);if(prev.side&&prev.side!==side)prev.flips.push(now);prev.side=side;signalStability.set(symbol,prev);if(prev.flips.length>=4){setAIGuard("AMBER","Rapid signal reversals detected on "+marketLabel(symbol)+". Waiting for 30 seconds of stable observations; this is a feed-instability warning, not proof of manipulation.");return;}const score=Number(s.evidenceScore||0),sample=Number(s.sample||0);if(score<80){setAIGuard("AMBER","Candidate quality is below the 80/100 execution threshold.");return;}if(Number(s.liveObservations||0)<20){setAIGuard("AMBER","Waiting for at least 20 distinct live quote changes on "+marketLabel(symbol)+" before execution.");return;}const digitContract=["DIGITOVER","DIGITUNDER","DIGITEVEN","DIGITODD"].includes(String(s.contract||""));const minimumSample=digitContract?600:120;if(sample<minimumSample){setAIGuard("AMBER","Insufficient historical observations for the execution guard: "+sample+"/"+minimumSample+".");return;}setAIGuard("GREEN","Signal passed 20+ distinct live quote changes, freshness, historical sample-size and quality checks. No active integrity warning.");}
function aiExecutionGate(){if(AI_GUARD.locked)return "AI protection is LOCKED for manual review: "+AI_GUARD.reason;if(AI_GUARD.state!=="GREEN")return "AI execution guard is "+AI_GUARD.state+": "+AI_GUARD.reason;return "";}
function tradeReadinessBlock(){
 const aiBlock=aiExecutionGate();if(aiBlock)return aiBlock;
 if(!account||account.account_type!=="demo")return "DEMO account required. REAL execution remains disabled.";
 if(!ws||ws.readyState!==WebSocket.OPEN)return "The public market feed may be connected, but the separate authenticated DEMO trading socket is not OPEN. Reconnect Deriv in the Execution Desk; trading remains safely blocked until it is.";
 if(!reconciliationReady)return "EXECUTION PAUSED — broker reconciliation is not currently confirmed for this authenticated socket. Wait for a fresh portfolio response; do not retry any uncertain purchase.";if(readPendingPurchase())return "EXECUTION PAUSED — an unresolved purchase safety lock exists for the selected DEMO account. Verify Deriv statement and open positions before clearing it.";
 if(busy||openContracts.size>=maxOpenTrades())return "A trade is already open or awaiting settlement.";
 const riskBlock=riskLimitReason();if(riskBlock)return riskBlock;
 const s=latestAnalysisSignal;
 if(!s||!coherentSignal(s))return "WAIT — no fresh, fully qualified live market signal.";
 if(!sameExecutionSignal(AI_GUARD.signal,s))return "WAIT — AI guard has not approved this exact market, contract, barrier and duration.";
 const p=params();
 if(String(p.underlying_symbol)!==String(s.symbol)||String(p.contract_type)!==String(s.contract)||Number(p.duration)!==Number(s.duration))return "WAIT — selected market, contract or duration does not match the AI-approved signal.";
 if(["DIGITOVER","DIGITUNDER"].includes(s.contract)&&Number(p.barrier)!==Number(s.barrier))return "WAIT — digit barrier does not match the AI-approved signal.";
 if(!proposal||!proposal.id||!quoteContextMatches())return "Market and AI checks agree. Waiting for a fresh matching Deriv payout quote.";
 if(!signalMatchesQuoteContext(s,proposalContext))return "EXECUTION CONSISTENCY LOCK — broker quote does not match the exact AI-approved market, contract, barrier and duration. Request a new quote.";
 if(!proposalReceivedAt||Date.now()-proposalReceivedAt>15000)return "WAIT — broker quote is older than 15 seconds. Request a fresh quote.";
 const ask=Number(proposal.ask_price),payout=Number(proposal.payout);
 if(!Number.isFinite(ask)||ask<=0||!Number.isFinite(payout)||payout<=ask)return "WAIT — broker payout/price is invalid.";
 const netReturn=(payout-ask)/ask*100,minReturn=Number($("bt-min-return")?.value||0);
 if(!Number.isFinite(netReturn)||netReturn<=minReturn)return "WAIT — quoted net return "+(Number.isFinite(netReturn)?netReturn.toFixed(1):"unavailable")+"% does not exceed the configured "+minReturn+"% minimum.";
 return "";
}
