function renderRisk(){if(!$("bt-risk-state"))return;ensureRiskDay();const reason=riskLimitReason(),blocked=!!reason;$("bt-risk-state").textContent=blocked?"TRADING PAUSED":"WITHIN LIMITS";$("bt-risk-state").style.color=blocked?"#ff7188":"#35e0a2";$("bt-risk-reason").textContent=reason||"Percentage limits are calculated from the latest verified broker balance.";$("bt-risk-pl").textContent=Number(riskState.sessionPL||0).toFixed(2);if($("bt-risk-daily-pl"))$("bt-risk-daily-pl").textContent=Number(riskState.dailyPL||0).toFixed(2);$("bt-risk-trades").textContent=String(riskState.dailyTrades);$("bt-risk-streak").textContent=String(riskState.lossStreak);if($("bt-buy"))$("bt-buy").disabled=blocked||AI_GUARD.state!=="GREEN"||AI_GUARD.locked||!proposal?.id||!reconciliationReady||!!readPendingPurchase()||!!tradeReadinessBlock();renderTradeReadiness();}
function recordRiskTrade(profit){ensureRiskDay();const result=Number(profit)||0;riskState.dailyTrades=(Number(riskState.dailyTrades)||0)+1;riskState.dailyPL+=result;riskState.sessionPL=(Number(riskState.sessionPL)||0)+result;if(result<0){riskState.lossStreak++;recentLossEvents.push({at:Date.now(),loss:Math.abs(result)});}else if(result>0)riskState.lossStreak=0;const now=Date.now();while(recentLossEvents.length&&now-recentLossEvents[0].at>CAPITAL_RISK.rapidLossWindowMs)recentLossEvents.shift();const rapidLoss=recentLossEvents.reduce((sum,x)=>sum+x.loss,0),rapidLimit=moneyFromCapital(CAPITAL_RISK.rapidLossPct);syncCapitalRisk(true);saveRiskState();persistAIGuard();if(rapidLimit>0&&rapidLoss>=rapidLimit)setAIGuard("RED","Rapid-loss protection: settled losses reached "+CAPITAL_RISK.rapidLossPct+"% of current capital within "+Math.round(CAPITAL_RISK.rapidLossWindowMs/1000)+" seconds. Automatic trading stopped; review results before restarting.",true);renderRisk();const limit=riskLimitReason();if(limit){setAIGuard("RED",limit,true);stopAuto(limit);say(limit);}}


