function resetDemoRecords(){
 if(!account||account.account_type!=="demo"){say("Select a DEMO account before resetting the app records.");return;}
 if(auto||busy||openContracts.size){say("Reset blocked: stop Auto and wait until every open contract is settled. No contract will be closed by this reset.");return;}
 const id=String(account.account_id||account.id||"");
 if(!id){say("Cannot identify the selected DEMO account; records were not changed.");return;}
 if(!confirm("Clear BERUR TRADES local journal and performance counters for this DEMO account? This cannot be undone. Open Deriv contracts and broker account history are not affected."))return;
 const prefixes=["berur-demo-journal-v1:"+id,"berur-risk-v1:"+id,"berur-session-counter-v1:"+id+":","berur-session-entry-v1:"+id+":"];
 try{const keys=[];for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k&&prefixes.some(p=>p.endsWith(":")?k.startsWith(p):k===p))keys.push(k);}keys.forEach(k=>localStorage.removeItem(k));}
 catch(e){say("Could not clear local records: "+e.message);return;}
 riskState={day:todayKey(),dailyPL:0,sessionPL:0,dailyTrades:0,lossStreak:0,halted:false,reason:""};
 activeSessionNo=0;activeSessionEntryNo=0;riskKey=riskStorageKey();saveRiskState();pl=0;trades=0;
 if($("bt-pl"))$("bt-pl").textContent="0.00";
 if($("bt-session-number"))$("bt-session-number").textContent="—";
 if($("bt-session-entries"))$("bt-session-entries").textContent="0";
 if($("bt-closed-history"))$("bt-closed-history").innerHTML="<tr><td colspan='5'>No closed trades yet.</td></tr>";
 if($("bt-closed-count"))$("bt-closed-count").textContent="0";
 renderRisk();renderJournal();
 say("Old local DEMO records cleared for this account. New performance tracking starts clean; broker history and open contracts remain untouched.");
}

