 if(!panel){panel=document.createElement("section");panel.id="berur-purchase-audit";panel.style.cssText="margin:14px 0;padding:14px;border:1px solid #34506f;border-radius:12px;background:#0d192b;color:#edf4ff";panel.innerHTML="<h3 style='margin:0 0 8px;font-size:13px'>PURCHASE LIFECYCLE AUDIT</h3><p style='margin:0 0 9px;color:#91a4bd;font-size:11px'>Signals, quotes and confirmed purchases are counted separately.</p><div id='berur-audit-summary' style='font-size:11px;margin-bottom:8px;color:#8de5c0'></div><div id='berur-audit-rows' style='overflow:auto'></div>";const target=document.getElementById("execution")||document.querySelector(".terminal-content")||document.body;target.appendChild(panel);}
