function reconcileBrokerTransactions(transactions){
 const grouped=new Map();
 (Array.isArray(transactions)?transactions:[]).forEach(tx=>{
  const id=String(tx?.contract_id||"");
  const action=String(tx?.action_type||tx?.action||"").toLowerCase();
  const amount=Number(tx?.amount);
  if(!id||!["buy","sell"].includes(action)||!Number.isFinite(amount))return;
  if(!grouped.has(id))grouped.set(id,{contractId:id,buyCount:0,sellCount:0,net:0,currency:tx.currency||account?.currency||"",transactions:[]});
  const item=grouped.get(id);item[action+"Count"]++;item.net+=amount;item.transactions.push(tx);
 });
 return Array.from(grouped.values()).filter(x=>x.buyCount>0&&x.sellCount>0);
}
