 const broker=reconcileBrokerTransactions(snapshot.transactions),profitRows=normalizeBrokerProfitRows(brokerProfitSnapshot?.transactions),local=readJournal().filter(x=>x.at>=Number(snapshot.from||0)*1000&&x.at<=Number(snapshot.to||Date.now()/1000)*1000),byId=new Map(local.filter(x=>x.contractId).map(x=>[String(x.contractId),x]));
