 const localOnly=local.filter(x=>x.contractId&&!brokerIds.has(String(x.contractId)));
 const brokerPL=broker.reduce((n,x)=>n+x.net,0),localPL=local.reduce((n,x)=>n+Number(x.profit||0),0),matchedDelta=matched.reduce((n,x)=>n+x.delta,0);
 const profitPL=profitRows.reduce((n,x)=>n+x.net,0),profitById=new Map(profitRows.map(x=>[x.contractId,x])),profitMatched=profitRows.filter(x=>byId.has(x.contractId)).map(x=>({broker:x,local:byId.get(x.contractId),delta:x.net-Number(byId.get(x.contractId).profit||0)})),profitDelta=profitMatched.reduce((n,x)=>n+x.delta,0);
 const money=n=>(n>=0?"+":"")+n.toFixed(2);
 panel.innerHTML="<b>DERIV BROKER HISTORY RECONCILIATION · READ ONLY</b><p>Statement received "+new Date(snapshot.at).toLocaleString()+" · "+snapshot.transactions.length+" transactions · last 30 days (maximum 999 transactions).</p><div style='display:flex;flex-wrap:wrap;gap:16px;margin:8px 0'><span>Broker closed contracts: <b>"+broker.length+"</b></span><span>Broker net P/L: <b>"+money(brokerPL)+" "+esc(account?.currency||"")+"</b></span><span>Local journal: <b>"+local.length+" trades · "+money(localPL)+"</b></span><span>Matched: <b>"+matched.length+"</b></span></div><p>Matched contract P/L difference: <b>"+money(matchedDelta)+"</b> · Broker-only: <b>"+brokerOnly.length+"</b> · Local-only / outside statement window: <b>"+localOnly.length+"</b></p><p><b>DERIV PROFIT TABLE (CLOSED CONTRACTS)</b> · "+(brokerProfitSnapshot?.loading?"Loading…":brokerProfitSnapshot?.error?"Unavailable":profitRows.length+" contracts")+" · Broker net P/L: <b>"+(brokerProfitSnapshot?.loading||brokerProfitSnapshot?.error?"—":money(profitPL))+"</b> · Matched local P/L difference: <b>"+(brokerProfitSnapshot?.loading||brokerProfitSnapshot?.error?"—":money(profitDelta))+"</b> · "+(brokerProfitSnapshot?.error?"Sync error: "+esc(brokerProfitSnapshot.error):brokerProfitSnapshot?.complete?"Complete for returned date range":profitRows.length>=500?"Page limit reached; more records may exist":"Awaiting profit-table response")+"</p><div style='overflow:auto'><table style='width:100%;border-collapse:collapse;font-size:11px'><thead><tr><th style='text-align:left;padding:6px'>Contract ID</th><th>Broker net</th><th>Local P/L</th><th>Difference</th><th>Status</th></tr></thead><tbody>"+matched.map(x=>"<tr><td style='padding:6px'>"+esc(x.broker.contractId)+"</td><td>"+money(x.broker.net)+"</td><td>"+money(Number(x.local.profit||0))+"</td><td>"+money(x.delta)+"</td><td>"+(Math.abs(x.delta)<0.011?"MATCH":"CHECK")+"</td></tr>").join("")+brokerOnly.map(x=>"<tr><td style='padding:6px'>"+esc(x.contractId)+"</td><td>"+money(x.net)+"</td><td>—</td><td>—</td><td>BROKER ONLY</td></tr>").join("")+localOnly.slice(0,30).map(x=>"<tr><td style='padding:6px'>"+esc(x.contractId)+"</td><td>—</td><td>"+money(Number(x.profit||0))+"</td><td>—</td><td>NOT IN 30-DAY RESULT</td></tr>").join("")+"</tbody></table></div><p style='color:#a9bad0'>Only contract IDs with both buy and sell transactions are counted as broker-closed. Open contracts and deposits/withdrawals are excluded. Local journal data is not overwritten; session attribution remains local. A difference or missing row requires checking the full Deriv statement.</p>";
